{
  "name": "NanoStudio AI",
  "description": "A professional AI product photography editor using the Nano Banana model. Upload your product, define the style, and generate stunning marketing assets in seconds."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum AspectRatio {
  SQUARE = "1:1",
  PORTRAIT = "3:4",
  LANDSCAPE = "4:3",
  MOBILE_PORTRAIT = "9:16",
  CINEMATIC = "16:9"
}

export enum LightingStyle {
  STUDIO = "Studio Lighting",
  NATURAL = "Natural Sunlight",
  NEON = "Neon Cyberpunk",
  DRAMATIC = "Dramatic Shadows",
  SOFTBOX = "Softbox Diffused",
  GOLDEN_HOUR = "Golden Hour"
}

export enum CameraPerspective {
  EYE_LEVEL = "Eye Level",
  TOP_DOWN = "Flat Lay (Top Down)",
  LOW_ANGLE = "Low Angle (Hero Shot)",
  MACRO = "Macro Close-up",
  ISOMETRIC = "Isometric View"
}

export interface GeneratedImageResponse {
  imageUrl: string | null;
  error?: string;
}

export interface GenerationConfig {
  productImageBase64: string;
  prompt: string;
  aspectRatio: string;
}

import { GoogleGenAI } from "@google/genai";

// Initialize the client
// Using process.env.API_KEY as per instructions
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Analyzes a style reference image to extract descriptive keywords.
 * Uses a text model (Gemini 3 Flash) for analysis.
 */
export const analyzeStyleReference = async (imageBase64: string): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg', // Assuming jpeg/png for simplicity, SDK handles most standard types
              data: imageBase64
            }
          },
          {
            text: "Analyze the artistic style, lighting, color palette, and composition of this image. Provide a concise, comma-separated list of visual descriptors suitable for an image generation prompt. Do not describe the subject matter, only the style."
          }
        ]
      }
    });

    return response.text || "";
  } catch (error) {
    console.error("Error analyzing style reference:", error);
    return "High quality, professional photography"; // Fallback
  }
};

/**
 * Generates the edited product image using Nano Banana (gemini-2.5-flash-image).
 */
export const generateEditedImage = async (
  productImageBase64: string,
  prompt: string,
  aspectRatio: string
): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image', // Nano Banana
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg',
              data: productImageBase64,
            },
          },
          {
            text: prompt,
          },
        ],
      },
      config: {
        imageConfig: {
          aspectRatio: aspectRatio,
        },
      },
    });

    // Check for inline data (the image)
    // The response candidates usually contain the image part
    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }

    throw new Error("No image data found in response");

  } catch (error) {
    console.error("Error generating image:", error);
    throw error;
  }
};

/**
 * Helper to convert Blob/File to Base64 string (without data prefix for API usage if needed, 
 * but @google/genai usually takes raw base64).
 * We will return the raw base64 string.
 */
export const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => {
      const result = reader.result as string;
      // Remove the data URL prefix (e.g., "data:image/jpeg;base64,")
      const base64 = result.split(',')[1];
      resolve(base64);
    };
    reader.onerror = (error) => reject(error);
  });
};

import React, { useRef, useState } from 'react';

interface ImageUploadProps {
  label: string;
  onImageSelected: (base64: string, file: File) => void;
  previewUrl: string | null;
  heightClass?: string;
  placeholderText?: string;
}

export const ImageUpload: React.FC<ImageUploadProps> = ({ 
  label, 
  onImageSelected, 
  previewUrl, 
  heightClass = "h-48",
  placeholderText = "Click to upload image"
}) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [isDragging, setIsDragging] = useState(false);

  const handleFileChange = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      processFile(file);
    }
  };

  const processFile = (file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      // Pass the full data URL for preview, and the raw file for processing
      // The parent handles the base64 stripping if needed
      onImageSelected(reader.result as string, file);
    };
    reader.readAsDataURL(file);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    const file = e.dataTransfer.files?.[0];
    if (file && file.type.startsWith('image/')) {
      processFile(file);
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = () => {
    setIsDragging(false);
  };

  return (
    <div className="flex flex-col gap-2 w-full">
      <label className="text-sm font-medium text-gray-300">{label}</label>
      <div 
        className={`relative w-full ${heightClass} border-2 border-dashed rounded-xl transition-all duration-200 cursor-pointer overflow-hidden
          ${isDragging 
            ? 'border-primary-500 bg-primary-500/10' 
            : 'border-gray-600 bg-gray-850 hover:border-gray-500'
          }
        `}
        onDrop={handleDrop}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onClick={() => fileInputRef.current?.click()}
      >
        {previewUrl ? (
          <img 
            src={previewUrl} 
            alt="Preview" 
            className="w-full h-full object-contain p-2"
          />
        ) : (
          <div className="absolute inset-0 flex flex-col items-center justify-center text-gray-400 gap-2">
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-8 h-8">
              <path strokeLinecap="round" strokeLinejoin="round" d="M3 16.5v2.25A2.25 2.25 0 0 0 5.25 21h13.5A2.25 2.25 0 0 0 21 18.75V16.5m-13.5-9L12 3m0 0 4.5 4.5M12 3v13.5" />
            </svg>
            <span className="text-xs text-center px-4">{placeholderText}</span>
          </div>
        )}
        <input 
          type="file" 
          ref={fileInputRef}
          onChange={handleFileChange} 
          accept="image/*" 
          className="hidden" 
        />
      </div>
    </div>
  );
};

