import { GoogleGenAI } from "@google/genai";

// Initialize the client
// Using process.env.API_KEY as per instructions
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Analyzes a style reference image to extract descriptive keywords.
 * Uses a text model (Gemini 3 Flash) for analysis.
 */
export const analyzeStyleReference = async (imageBase64: string): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg', // Assuming jpeg/png for simplicity, SDK handles most standard types
              data: imageBase64
            }
          },
          {
            text: "Analyze the provided image and generate a detailed, descriptive prompt that captures its artistic style. Focus on the lighting (direction, quality, color), the color palette, the background texture and environment, and the camera perspective/depth of field. Do not simply list keywords; write a coherent description of the visual mood and aesthetic. Do not mention the specific object shown in the reference image; focus purely on the photographic style."
          }
        ]
      }
    });

    return response.text || "";
  } catch (error) {
    console.error("Error analyzing style reference:", error);
    return "High quality, professional photography with excellent lighting and composition."; // Fallback
  }
};

/**
 * Generates the edited product image using Nano Banana (gemini-2.5-flash-image).
 */
export const generateEditedImage = async (
  productImageBase64: string,
  prompt: string,
  aspectRatio: string
): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image', // Nano Banana
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg',
              data: productImageBase64,
            },
          },
          {
            text: prompt,
          },
        ],
      },
      config: {
        imageConfig: {
          aspectRatio: aspectRatio,
        },
      },
    });

    // Check for inline data (the image)
    // The response candidates usually contain the image part
    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }

    throw new Error("No image data found in response");

  } catch (error) {
    console.error("Error generating image:", error);
    throw error;
  }
};

/**
 * Helper to convert Blob/File to Base64 string (without data prefix for API usage if needed, 
 * but @google/genai usually takes raw base64).
 * We will return the raw base64 string.
 */
export const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => {
      const result = reader.result as string;
      // Remove the data URL prefix (e.g., "data:image/jpeg;base64,")
      const base64 = result.split(',')[1];
      resolve(base64);
    };
    reader.onerror = (error) => reject(error);
  });
};

