import React, { useState, useEffect, useCallback } from 'react';
import { ImageUpload } from './components/ImageUpload';
import { Controls } from './components/Controls';
import { AspectRatio, LightingStyle, CameraPerspective, HistoryItem } from './types';
import { analyzeStyleReference, generateEditedImage, fileToBase64 } from './services/geminiService';

const App: React.FC = () => {
  // Mode State: ON = Auto/Creative, OFF = Manual/Scene Preservation
  const [mode, setMode] = useState<'ON' | 'OFF'>('ON');

  // State for Inputs
  const [productImage, setProductImage] = useState<string | null>(null);
  const [productImageRaw, setProductImageRaw] = useState<File | null>(null);

  const [styleImage, setStyleImage] = useState<string | null>(null);
  const [styleImageRaw, setStyleImageRaw] = useState<File | null>(null);
  const [styleDescription, setStyleDescription] = useState<string>("");
  const [isAnalyzingStyle, setIsAnalyzingStyle] = useState<boolean>(false);

  // State for Controls
  const [aspectRatio, setAspectRatio] = useState<AspectRatio>(AspectRatio.SQUARE);
  const [lighting, setLighting] = useState<LightingStyle>(LightingStyle.STUDIO);
  const [perspective, setPerspective] = useState<CameraPerspective>(CameraPerspective.EYE_LEVEL);

  // State for Prompt
  const [prompt, setPrompt] = useState<string>("");

  // State for Generation
  const [isGenerating, setIsGenerating] = useState<boolean>(false);
  const [generatedImage, setGeneratedImage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  // State for Lightbox
  const [isLightboxOpen, setIsLightboxOpen] = useState<boolean>(false);

  // State for History
  const [history, setHistory] = useState<HistoryItem[]>([]);

  // Update prompt whenever controls or style description changes (ONLY IN ON MODE)
  useEffect(() => {
    if (mode === 'OFF') return;

    let constructedPrompt = "Professional product photography.";

    if (styleDescription) {
      // Directly incorporate the detailed style description
      constructedPrompt += `\n\nVISUAL STYLE:\n${styleDescription}`;
    } else {
      constructedPrompt += " Create a high-quality, realistic image.";
    }

    constructedPrompt += `\n\nSETTINGS:\nLighting: ${lighting}\nCamera Perspective: ${perspective}`;

    // Add a closing instruction to ensure the product is central
    constructedPrompt += "\n\nEnsure the product is naturally integrated into this environment with matching lighting and shadows.";

    setPrompt(constructedPrompt);
  }, [lighting, perspective, styleDescription, mode]);

  // When Mode switches to OFF, clear the auto-generated prompt if user hasn't typed
  useEffect(() => {
    if (mode === 'OFF') {
      setPrompt("");
    } else {
      // Trigger prompt regeneration by touching state
      setPerspective(prev => prev); 
    }
  }, [mode]);

  // Handle Style Image Upload
  const handleStyleImageSelect = async (base64: string, file: File) => {
    setStyleImage(base64);
    setStyleImageRaw(file);

    // Only analyze if in ON mode
    if (mode === 'ON') {
      setIsAnalyzingStyle(true);
      try {
        const rawBase64 = await fileToBase64(file);
        const description = await analyzeStyleReference(rawBase64);
        setStyleDescription(description);
      } catch (err) {
        console.error(err);
        setError("Failed to analyze style reference image.");
      } finally {
        setIsAnalyzingStyle(false);
      }
    } else {
      // In OFF mode, reset description as we don't use it for text gen
      setStyleDescription("");
    }
  };

  // Re-trigger analysis if switching to ON mode while an image is already uploaded but not analyzed
  useEffect(() => {
    const triggerAnalysis = async () => {
      if (mode === 'ON' && styleImageRaw && !styleDescription && !isAnalyzingStyle) {
        setIsAnalyzingStyle(true);
        try {
          const rawBase64 = await fileToBase64(styleImageRaw);
          const description = await analyzeStyleReference(rawBase64);
          setStyleDescription(description);
        } catch (err) {
          console.error(err);
        } finally {
          setIsAnalyzingStyle(false);
        }
      }
    };
    triggerAnalysis();
  }, [mode, styleImageRaw, styleDescription, isAnalyzingStyle]);

  const handleProductImageSelect = (_base64: string, file: File) => {
    setProductImage(_base64);
    setProductImageRaw(file);
    // Reset generation when new product uploaded
    setGeneratedImage(null);
  };

  const handleGenerate = async () => {
    if (!productImageRaw) {
      setError("Please upload a product image.");
      return;
    }

    setIsGenerating(true);
    setError(null);
    setGeneratedImage(null);

    try {
      const productBase64 = await fileToBase64(productImageRaw);

      let finalPrompt = prompt;
      let referenceImageBase64: string | undefined = undefined;

      if (mode === 'OFF') {
        // SCENE PRESERVATION MODE
        if (styleImageRaw) {
          referenceImageBase64 = await fileToBase64(styleImageRaw);

          if (!finalPrompt.trim()) {
            // Auto prompt for OFF mode if user provided no text
            finalPrompt = "Seamlessly insert the first image (product) into the second image (scene). Preserve the scene's lighting, perspective, and background details accurately. Replace any existing subject in the scene with the new product.";
          }
        } else if (!finalPrompt.trim()) {
           setError("In Manual mode, please provide a prompt or a scene reference image.");
           setIsGenerating(false);
           return;
        }
      } else {
        // ON MODE (Creative)
        // Standard prompt (already generated in state) + Product Image only
        if (!finalPrompt) {
          setError("Generating prompt...");
          return;
        }
      }

      const resultImageUrl = await generateEditedImage(productBase64, finalPrompt, aspectRatio, referenceImageBase64);

      setGeneratedImage(resultImageUrl);

      // Add to history
      setHistory(prev => [
        {
          id: Date.now().toString(),
          imageUrl: resultImageUrl,
          timestamp: Date.now()
        },
        ...prev
      ]);

    } catch (err) {
      console.error(err);
      setError("Failed to generate image. Please try again.");
    } finally {
      setIsGenerating(false);
    }
  };

  // Prevent scrolling when lightbox is open
  useEffect(() => {
    if (isLightboxOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
    return () => {
      document.body.style.overflow = 'unset';
    };
  }, [isLightboxOpen]);

  return (
    <div className="min-h-screen bg-gray-950 text-gray-100 font-sans selection:bg-primary-500 selection:text-white">
      {/* Header */}
      <header className="border-b border-gray-800 bg-gray-900/50 backdrop-blur-md sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-primary-400 to-primary-600 flex items-center justify-center">
              <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" className="w-5 h-5 text-white">
                <path fillRule="evenodd" d="M1.5 6a2.25 2.25 0 0 1 2.25-2.25h16.5A2.25 2.25 0 0 1 22.5 6v12a2.25 2.25 0 0 1-2.25 2.25H3.75A2.25 2.25 0 0 1 1.5 18V6ZM3 16.06V18c0 .414.336.75.75.75h16.5A.75.75 0 0 0 21 18v-1.94l-2.69-2.689a1.5 1.5 0 0 0-2.12 0l-.88.879.97.97a.75.75 0 1 1-1.06 1.06l-5.16-5.159a1.5 1.5 0 0 0-2.12 0L3 16.061Zm10.125-7.81a1.125 1.125 0 1 1 2.25 0 1.125 1.125 0 0 1-2.25 0Z" clipRule="evenodd" />
              </svg>
            </div>
            <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-gray-100 to-gray-400">
              NanoStudio AI
            </h1>
          </div>
          <div className="text-xs text-gray-500 font-mono">Powered by Gemini 2.5</div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-8">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

          {/* LEFT COLUMN: Controls & Inputs */}
          <div className="lg:col-span-5 flex flex-col gap-8">

            {/* Step 1: Uploads */}
            <div className="space-y-6 bg-gray-900/50 p-6 rounded-2xl border border-gray-800">
              <h2 className="text-lg font-semibold flex items-center gap-2">
                <span className="w-6 h-6 rounded-full bg-gray-800 text-gray-400 text-xs flex items-center justify-center border border-gray-700">1</span>
                Upload Assets
              </h2>

              <ImageUpload 
                label="Product Image (Subject)" 
                onImageSelected={handleProductImageSelect} 
                previewUrl={productImage}
                heightClass="h-56"
              />

              <div className="pt-2 border-t border-gray-800/50">
                <div className="flex justify-between items-center mb-2">
                  <label className="text-sm font-medium text-gray-300">
                    {mode === 'ON' ? 'Style Reference (Optional)' : 'Scene Background (Optional)'}
                  </label>
                  {isAnalyzingStyle && mode === 'ON' && <span className="text-xs text-primary-400 animate-pulse">Analyzing style...</span>}
                </div>
                <ImageUpload 
                  label=""
                  placeholderText={mode === 'ON' ? "Upload an image to copy its vibe" : "Upload a background scene"}
                  onImageSelected={handleStyleImageSelect} 
                  previewUrl={styleImage}
                  heightClass="h-24"
                />
              </div>
            </div>

            {/* Step 2: Settings */}
            <div className="space-y-6 bg-gray-900/50 p-6 rounded-2xl border border-gray-800">
              <h2 className="text-lg font-semibold flex items-center gap-2">
                 <span className="w-6 h-6 rounded-full bg-gray-800 text-gray-400 text-xs flex items-center justify-center border border-gray-700">2</span>
                Configuration
              </h2>
              <Controls 
                aspectRatio={aspectRatio} setAspectRatio={setAspectRatio}
                lighting={lighting} setLighting={setLighting}
                perspective={perspective} setPerspective={setPerspective}
                mode={mode} setMode={setMode}
              />
            </div>

            {/* Step 3: Prompt */}
            <div className="space-y-4 bg-gray-900/50 p-6 rounded-2xl border border-gray-800">
              <h2 className="text-lg font-semibold flex items-center gap-2">
                 <span className="w-6 h-6 rounded-full bg-gray-800 text-gray-400 text-xs flex items-center justify-center border border-gray-700">3</span>
                {mode === 'ON' ? 'Generated Prompt' : 'Manual Prompt'}
              </h2>
              <p className="text-xs text-gray-400">
                {mode === 'ON' 
                  ? "AI generated prompt based on your settings. You can edit this manually for fine-tuning."
                  : "Enter instructions for the scene replacement, or leave empty for auto-composition."
                }
              </p>
              <textarea
                value={prompt}
                onChange={(e) => setPrompt(e.target.value)}
                className="w-full h-32 bg-gray-950 border border-gray-700 rounded-lg p-4 text-sm text-gray-200 focus:ring-1 focus:ring-primary-500 focus:border-primary-500 resize-none font-mono leading-relaxed"
                placeholder={mode === 'ON' ? "Prompt will appear here..." : "e.g., Place the product on the wooden table..."}
              />
            </div>

            {/* Action */}
            <button
              onClick={handleGenerate}
              disabled={!productImage || isGenerating || isAnalyzingStyle}
              className={`
                sticky bottom-6 z-40 w-full py-4 px-6 rounded-xl font-bold text-lg shadow-lg transition-all transform active:scale-[0.98]
                flex items-center justify-center gap-3
                ${!productImage || isGenerating || isAnalyzingStyle
                  ? 'bg-gray-800 text-gray-500 cursor-not-allowed' 
                  : 'bg-gradient-to-r from-primary-600 to-primary-500 hover:from-primary-500 hover:to-primary-400 text-white shadow-primary-900/20'
                }
              `}
            >
              {isGenerating ? (
                <>
                  <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                  </svg>
                  Processing...
                </>
              ) : (
                <>
                  <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" className="w-5 h-5">
                    <path fillRule="evenodd" d="M9.315 7.584C12.195 3.883 16.695 1.5 21.75 1.5a.75.75 0 0 1 .75.75c0 5.056-2.383 9.555-6.084 12.436h.001c-3.3 2.567-6.93 2.567-9.691 2.567H3.25C1.83 17.253.375 18.064.375 20.25a.75.75 0 0 0 .75.75h21.75a.75.75 0 0 0 .75-.75c0-2.186-1.455-2.997-2.875-2.997H16.19c-2.76 0-6.39 0-9.69-2.567C2.882 11.952.5 7.452.5 2.396a.75.75 0 0 1 .75-.75c5.055 0 9.555 2.383 12.436 6.084l-3.375 3.375-3.001-3.52Z" clipRule="evenodd" />
                  </svg>
                  Generate Image
                </>
              )}
            </button>
            {error && (
              <div className="p-4 bg-red-900/20 border border-red-800 text-red-200 rounded-lg text-sm">
                {error}
              </div>
            )}
          </div>

          {/* RIGHT COLUMN: Output */}
          <div className="lg:col-span-7 flex flex-col gap-6">
            <div className="bg-gray-900/50 border border-gray-800 rounded-2xl p-2 h-[600px] flex flex-col relative overflow-hidden group">
              <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-20 pointer-events-none"></div>

              {generatedImage ? (
                <div className="relative w-full h-full flex items-center justify-center bg-black rounded-xl overflow-hidden group/image">
                   <img 
                    src={generatedImage} 
                    alt="Generated Product" 
                    className="max-w-full max-h-full object-contain shadow-2xl cursor-zoom-in transition-transform duration-300 group-hover/image:scale-[1.01]"
                    onClick={() => setIsLightboxOpen(true)}
                  />
                  <a 
                    href={generatedImage} 
                    download="nanostudio-edit.png"
                    className="absolute top-4 right-4 bg-black/50 hover:bg-black/70 backdrop-blur-md text-white px-4 py-2 rounded-full text-sm font-medium transition-colors border border-white/10 flex items-center gap-2 z-10"
                    onClick={(e) => e.stopPropagation()}
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4">
                      <path strokeLinecap="round" strokeLinejoin="round" d="M3 16.5v2.25A2.25 2.25 0 0 0 5.25 21h13.5A2.25 2.25 0 0 0 21 18.75V16.5M12 9.75v10.5m0 0L7.5 15.75M12 20.25l4.5-4.5M12 3v9" />
                    </svg>
                    Download
                  </a>
                  <div className="absolute bottom-4 left-1/2 -translate-x-1/2 opacity-0 group-hover/image:opacity-100 transition-opacity bg-black/50 backdrop-blur-md px-3 py-1 rounded-full text-xs text-white/80 pointer-events-none">
                    Click to enlarge
                  </div>
                </div>
              ) : (
                <div className="w-full h-full flex flex-col items-center justify-center text-gray-600 gap-4 bg-gray-950/50 rounded-xl">
                  {isGenerating ? (
                    <div className="flex flex-col items-center gap-4 animate-pulse">
                      <div className="w-16 h-16 rounded-full bg-gray-800"></div>
                      <div className="h-4 w-32 bg-gray-800 rounded"></div>
                    </div>
                  ) : (
                    <>
                      <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1} stroke="currentColor" className="w-24 h-24 opacity-20">
                        <path strokeLinecap="round" strokeLinejoin="round" d="m2.25 15.75 5.159-5.159a2.25 2.25 0 0 1 3.182 0l5.159 5.159m-1.5-1.5 1.409-1.409a2.25 2.25 0 0 1 3.182 0l2.909 2.909m-18 3.75h16.5a1.5 1.5 0 0 0 1.5-1.5V6a1.5 1.5 0 0 0-1.5-1.5H3.75A1.5 1.5 0 0 0 2.25 6v12a1.5 1.5 0 0 0 1.5 1.5Zm10.5-11.25h.008v.008h-.008V8.25Zm.375 0a.375.375 0 1 1-.75 0 .375.375 0 0 1 .75 0Z" />
                      </svg>
                      <p className="text-gray-500">Result will appear here</p>
                    </>
                  )}
                </div>
              )}
            </div>

            {/* History Section */}
            {history.length > 0 && (
              <div className="bg-gray-900/50 border border-gray-800 rounded-2xl p-6">
                <div className="flex items-center justify-between mb-4">
                  <h3 className="text-sm font-semibold text-gray-400 uppercase tracking-wider">Recent Generations</h3>
                  <button 
                    onClick={() => setHistory([])}
                    className="text-xs text-gray-500 hover:text-red-400 transition-colors"
                  >
                    Clear History
                  </button>
                </div>
                <div className="flex gap-4 overflow-x-auto pb-2 scrollbar-thin scrollbar-thumb-gray-700 scrollbar-track-transparent">
                  {history.map(item => (
                    <button
                      key={item.id}
                      onClick={() => setGeneratedImage(item.imageUrl)}
                      className={`relative flex-shrink-0 w-24 h-24 rounded-lg overflow-hidden border-2 transition-all group ${
