import React, { useRef, useState } from 'react';
import { UploadedImage } from '../types';

interface ImageUploadProps {
  label: string;
  images: UploadedImage[];
  onImagesAdded: (newImages: UploadedImage[]) => void;
  onImageRemoved: (id: string) => void;
  heightClass?: string;
  placeholderText?: string;
}

export const ImageUpload: React.FC<ImageUploadProps> = ({ 
  label, 
  images, 
  onImagesAdded, 
  onImageRemoved,
  heightClass = "h-48",
  placeholderText = "Click or drop images here"
}) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [isDragging, setIsDragging] = useState(false);

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    if (event.target.files && event.target.files.length > 0) {
      processFiles(Array.from(event.target.files));
    }
    // Reset input value so same files can be selected again if needed
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  const processFiles = (files: File[]) => {
    const newImages: UploadedImage[] = [];
    let processedCount = 0;

    files.forEach(file => {
      const reader = new FileReader();
      reader.onloadend = () => {
        newImages.push({
          id: Math.random().toString(36).substr(2, 9),
          base64: reader.result as string,
          file: file
        });
        processedCount++;

        if (processedCount === files.length) {
          onImagesAdded(newImages);
        }
      };
      reader.readAsDataURL(file);
    });
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);

    const droppedFiles = Array.from(e.dataTransfer.files).filter(file => 
      file.type.startsWith('image/')
    );

    if (droppedFiles.length > 0) {
      processFiles(droppedFiles);
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = () => {
    setIsDragging(false);
  };

  return (
    <div className="flex flex-col gap-2 w-full">
      <div className="flex justify-between items-end">
        <label className="text-sm font-medium text-gray-300">{label}</label>
        <span className="text-xs text-gray-500">{images.length} item{images.length !== 1 && 's'}</span>
      </div>

      {/* Drop Zone */}
      <div 
        className={`relative w-full transition-all duration-200 cursor-pointer overflow-hidden border-2 border-dashed rounded-xl
          ${isDragging 
            ? 'border-primary-500 bg-primary-500/10' 
            : 'border-gray-600 bg-gray-850 hover:border-gray-500'
          }
          ${images.length > 0 ? 'h-auto min-h-[100px] p-4' : heightClass}
        `}
        onDrop={handleDrop}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onClick={(e) => {
          // Prevent triggering file input when clicking remove button
          if ((e.target as HTMLElement).closest('button')) return;
          fileInputRef.current?.click();
        }}
      >
        <input 
          type="file" 
          ref={fileInputRef}
          onChange={handleFileChange} 
          accept="image/*" 
          multiple
          className="hidden" 
        />

        {images.length === 0 ? (
          <div className="absolute inset-0 flex flex-col items-center justify-center text-gray-400 gap-2 pointer-events-none">
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-8 h-8">
              <path strokeLinecap="round" strokeLinejoin="round" d="M3 16.5v2.25A2.25 2.25 0 0 0 5.25 21h13.5A2.25 2.25 0 0 0 21 18.75V16.5m-13.5-9L12 3m0 0 4.5 4.5M12 3v13.5" />
            </svg>
            <span className="text-xs text-center px-4">{placeholderText}</span>
          </div>
        ) : (
          <div className="grid grid-cols-3 gap-3">
             {images.map((img) => (
               <div key={img.id} className="relative aspect-square rounded-lg overflow-hidden group border border-gray-700 bg-black">
                 <img 
                   src={img.base64} 
                   alt="Upload" 
                   className="w-full h-full object-cover opacity-80 group-hover:opacity-100 transition-opacity"
                 />
                 <button
                   onClick={() => onImageRemoved(img.id)}
                   className="absolute top-1 right-1 bg-black/60 hover:bg-red-500/80 text-white rounded-full p-1 transition-colors backdrop-blur-sm opacity-0 group-hover:opacity-100"
                   title="Remove image"
                 >
                   <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-4 h-4">
                     <path d="M6.28 5.22a.75.75 0 00-1.06 1.06L8.94 10l-3.72 3.72a.75.75 0 101.06 1.06L10 11.06l3.72 3.72a.75.75 0 101.06-1.06L11.06 10l3.72-3.72a.75.75 0 00-1.06-1.06L10 8.94 6.28 5.22z" />
                   </svg>
                 </button>
               </div>
             ))}
             {/* Add More Button */}
             <div className="aspect-square rounded-lg border border-dashed border-gray-600 flex items-center justify-center hover:bg-gray-800 transition-colors text-gray-500">
               <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-6 h-6">
                 <path strokeLinecap="round" strokeLinejoin="round" d="M12 4.5v15m7.5-7.5h-15" />
               </svg>
             </div>
          </div>
        )}
      </div>
    </div>
  );
};

import { GoogleGenAI } from "@google/genai";

// Initialize the client
// Using process.env.API_KEY as per instructions
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Analyzes style reference images to extract descriptive keywords.
 * Uses a text model (Gemini 3 Flash) for analysis.
 * Accepts multiple images.
 */
export const analyzeStyleReference = async (imagesBase64: string[]): Promise<string> => {
  if (imagesBase64.length === 0) return "";

  try {
    const parts: any[] = [];

    // Add all images as parts
    imagesBase64.forEach(base64 => {
      // Clean base64 just in case, though usually handled by caller
      const cleanBase64 = base64.includes(',') ? base64.split(',')[1] : base64;
      parts.push({
        inlineData: {
          mimeType: 'image/jpeg',
          data: cleanBase64
        }
      });
    });

    parts.push({
      text: "Analyze the provided image(s) and generate a detailed, descriptive prompt that captures their collective artistic style. Focus on the lighting (direction, quality, color), the color palette, the background texture and environment, and the camera perspective/depth of field. Do not simply list keywords; write a coherent description of the visual mood and aesthetic. Do not mention specific objects shown in the reference images; focus purely on the photographic style."
    });

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts }
    });

    return response.text || "";
  } catch (error) {
    console.error("Error analyzing style reference:", error);
    return "High quality, professional photography with excellent lighting and composition."; // Fallback
  }
};

/**
 * Generates the edited product image using Nano Banana (gemini-2.5-flash-image).
 * Supports arrays of product images and optional reference images.
 */
export const generateEditedImage = async (
  productImagesBase64: string[],
  prompt: string,
  aspectRatio: string,
  referenceImagesBase64: string[] = []
): Promise<string> => {
  try {
    const parts: any[] = [];

    // Add Product Images
    productImagesBase64.forEach(base64 => {
      const cleanBase64 = base64.includes(',') ? base64.split(',')[1] : base64;
      parts.push({
        inlineData: {
          mimeType: 'image/jpeg',
          data: cleanBase64,
        },
      });
    });

    // Add Reference Images (if any)
    referenceImagesBase64.forEach(base64 => {
      const cleanBase64 = base64.includes(',') ? base64.split(',')[1] : base64;
      parts.push({
        inlineData: {
          mimeType: 'image/jpeg',
          data: cleanBase64,
        },
      });
    });

    // Add the text prompt last
    parts.push({ text: prompt });

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image', // Nano Banana
      contents: { parts },
      config: {
        imageConfig: {
          aspectRatio: aspectRatio,
        },
      },
    });

    // Check for inline data (the image)
    // The response candidates usually contain the image part
    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }

    throw new Error("No image data found in response");

  } catch (error) {
    console.error("Error generating image:", error);
    throw error;
  }
};

/**
 * Helper to convert Blob/File to Base64 string (without data prefix for API usage if needed, 
 * but @google/genai usually takes raw base64).
 * We will return the raw base64 string.
 */
export const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => {
      const result = reader.result as string;
      // Remove the data URL prefix (e.g., "data:image/jpeg;base64,")
      const base64 = result.split(',')[1];
      resolve(base64);
    };
    reader.onerror = (error) => reject(error);
  });
};

import React, { useState, useEffect, useCallback } from 'react';
import { ImageUpload } from './components/ImageUpload';
