  const [isGenerating, setIsGenerating] = useState<boolean>(false);
  const [generatedImage, setGeneratedImage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  // State for Lightbox
  const [isLightboxOpen, setIsLightboxOpen] = useState<boolean>(false);

  // State for History
  const [history, setHistory] = useState<HistoryItem[]>([]);

  // Update prompt whenever controls or style description changes (ONLY IN ON MODE)
  useEffect(() => {
    if (mode === 'OFF') return;

    // 1. Analysis Section
    let analysisSection = "";
    if (styleDescription) {
      analysisSection = `*** STYLE ANALYSIS & INFERENCE ***\n${styleDescription}\n\n`;
    }

    // 2. The Fixed Base Prompt with Dynamic Values
    const baseRules = `Generate a photorealistic, high-end product photograph.
- Subject: The product is featured in the provided image. Keep it completely unaltered.
- Style: Clean, modern, and professional.
- Lighting: ${lighting}
- Perspective: ${perspective}

- The final image aspect ratio is set to ${aspectRatio}.
- CRITICAL: Preserve the final output dimensions with NO empty white areas.
- Extend the scene naturally (background, ground texture, atmosphere, lighting) to fill the ENTIRE frame from corner to corner.
- There must be ZERO white space, borders, or padding in the final result.
- Seamlessly integrate all subjects into this full-bleed environment.
- STRICT REQUIREMENT: The final generated image must be completely free of text, writing, logos, symbols, and watermarks. Even if the style reference contains text, IGNORE IT. The output must be purely visual pixels with no typography.
- TEXT BAN: Ensure NO letters, NO characters, and NO written language appear anywhere in the scene.
- COUNT RULE: Use ONLY the ${productImages.length} uploaded product(s). IGNORE the number of products shown in the style reference images. Do not generate extra products to match the reference style.
- PACKAGING PRESERVATION: Treat each product image as a fixed visual object. Keep every product’s packaging design exactly as it is (logo, label layout, graphics, typography, and key brand colors). Do NOT create new product variations or SKUs, and do NOT replace the printed design on the packaging. Do NOT mix details between products.
- TRUE COLOR PRESERVATION: Do NOT change or replace the product’s original body color. Always use the real color shown in the uploaded product photo as the primary, fixed color. Printed visuals on the packaging (artwork, icons, fruits, patterns, label graphics) must be preserved exactly as they are, but they should NOT be used to generate a new body color or recolor the product. Meaning: Keep the original product color exactly as it is, and keep the printed elements exactly as they are — but do not use those printed elements as a reason to recolor the product.
- MULTI-PRODUCT INDEPENDENCE: When multiple products are uploaded, keep each product’s original color exactly as it is. Do NOT harmonize, unify, adjust, or change the colors of any product to match the others. Each product keeps its own color independently.
- COLOR & MOOD: You ARE allowed to use the style reference to influence the color mood and overall color grading of the scene and products (e.g. warmer, cooler, more saturated), as long as the original design, flavor, and branding of each product remain clearly recognizable and unchanged.
- CREATIVE SCOPE: Use the reference for environment, lighting, mood, effects, composition, and overall color atmosphere. All creative work should happen AROUND the products and through global grading, not by repainting the packaging.
- RETOUCHING: External retouching effects (lighting, reflections, highlights, shadows, water droplets, atmosphere) are allowed ON TOP of the product, but never inside or replacing its design.
- POSITION & GROUNDING: Always match the product’s physical position in the style reference. If the reference shows the product touching the ground, surface, or table, keep the product grounded with a proper shadow and contact lighting. Do NOT make the product float unless the reference itself shows the product floating. Floating fruits, effects, or particles in the reference do NOT mean the product should float — only the secondary elements may move.`;

    // Combine them
    setPrompt(`${analysisSection}${baseRules}`);

  }, [lighting, perspective, aspectRatio, productImages.length, styleDescription, mode]);

  // When Mode switches to OFF, clear the auto-generated prompt if user hasn't typed
  useEffect(() => {
    if (mode === 'OFF') {
      setPrompt("");
    } else {
      // Trigger prompt regeneration by touching state
      setPerspective(prev => prev); 
      // Trigger analysis if we have style images but no description yet
      if (styleImages.length > 0 && !styleDescription) {
        analyzeStyles(styleImages);
      }
    }
  }, [mode]);

  // Helper to extract clean base64s from UploadedImage array
  const getCleanBase64s = (images: UploadedImage[]) => {
    return images.map(img => img.base64.split(',')[1]);
  };

  const analyzeStyles = async (images: UploadedImage[]) => {
    if (images.length === 0) return;

    setIsAnalyzingStyle(true);
    try {
      const base64s = getCleanBase64s(images);
      const description = await analyzeStyleReference(base64s);
      setStyleDescription(description);
    } catch (err) {
      console.error(err);
      setError("Failed to analyze style reference images.");
    } finally {
      setIsAnalyzingStyle(false);
    }
  };

  // Handle Style Image Updates
  const handleStyleImagesAdded = (newImages: UploadedImage[]) => {
    const updated = [...styleImages, ...newImages];
    setStyleImages(updated);

    // Only analyze if in ON mode
    if (mode === 'ON') {
      analyzeStyles(updated);
    } else {
      setStyleDescription("");
    }
  };

  const handleStyleImageRemoved = (id: string) => {
    const updated = styleImages.filter(img => img.id !== id);
    setStyleImages(updated);

    if (mode === 'ON' && updated.length > 0) {
      analyzeStyles(updated);
    } else if (updated.length === 0) {
      setStyleDescription("");
    }
  };

  // Handle Product Image Updates
  const handleProductImagesAdded = (newImages: UploadedImage[]) => {
    setProductImages(prev => [...prev, ...newImages]);
    // Reset generation when new product uploaded
    setGeneratedImage(null);
  };

  const handleProductImageRemoved = (id: string) => {
    setProductImages(prev => prev.filter(img => img.id !== id));
  };

  const handleGenerate = async () => {
    if (productImages.length === 0) {
      setError("Please upload at least one product image.");
      return;
    }

    setIsGenerating(true);
    setError(null);
    setGeneratedImage(null);

    try {
      const productBase64s = getCleanBase64s(productImages);
      let referenceBase64s: string[] = [];
      let finalPrompt = prompt;

      if (mode === 'OFF') {
        // SCENE PRESERVATION MODE
        // We pass styleImages as reference scenes
        if (styleImages.length > 0) {
          referenceBase64s = getCleanBase64s(styleImages);

          if (!finalPrompt.trim()) {
            finalPrompt = "Seamlessly insert the product image(s) into the scene image(s). Preserve the scene's lighting, perspective, and background details accurately. Replace any existing subject in the scene with the new product.";
          }
        } else if (!finalPrompt.trim()) {
           setError("In Manual mode, please provide a prompt or a scene reference image.");
           setIsGenerating(false);
           return;
        }
      } else {
        // ON MODE (Creative)
        if (!finalPrompt) {
          setError("Generating prompt...");
          return;
        }
      }

      // We now pass the full prompt (which includes rules) to the service
      const resultImageUrl = await generateEditedImage(
        productBase64s, 
        finalPrompt, 
        aspectRatio, 
        referenceBase64s
      );

      setGeneratedImage(resultImageUrl);

      // Add to history
      setHistory(prev => [
        {
          id: Date.now().toString(),
          imageUrl: resultImageUrl,
          timestamp: Date.now()
        },
        ...prev
      ]);

    } catch (err) {
      console.error(err);
      setError("Failed to generate image. Please try again.");
    } finally {
      setIsGenerating(false);
    }
  };

  // Prevent scrolling when lightbox is open
  useEffect(() => {
    if (isLightboxOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
    return () => {
      document.body.style.overflow = 'unset';
    };
  }, [isLightboxOpen]);

  return (
    <div className="min-h-screen bg-gray-950 text-gray-100 font-sans selection:bg-primary-500 selection:text-white">
      {/* Header */}
      <header className="border-b border-gray-800 bg-gray-900/50 backdrop-blur-md sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-primary-400 to-primary-600 flex items-center justify-center">
              <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" className="w-5 h-5 text-white">
                <path fillRule="evenodd" d="M1.5 6a2.25 2.25 0 0 1 2.25-2.25h16.5A2.25 2.25 0 0 1 22.5 6v12a2.25 2.25 0 0 1-2.25 2.25H3.75A2.25 2.25 0 0 1 1.5 18V6ZM3 16.06V18c0 .414.336.75.75.75h16.5A.75.75 0 0 0 21 18v-1.94l-2.69-2.689a1.5 1.5 0 0 0-2.12 0l-.88.879.97.97a.75.75 0 1 1-1.06 1.06l-5.16-5.159a1.5 1.5 0 0 0-2.12 0L3 16.061Zm10.125-7.81a1.125 1.125 0 1 1 2.25 0 1.125 1.125 0 0 1-2.25 0Z" clipRule="evenodd" />
              </svg>
            </div>
            <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-gray-100 to-gray-400">
              NanoStudio AI
            </h1>
          </div>
          <div className="text-xs text-gray-500 font-mono">Powered by Gemini 2.5</div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-8">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

          {/* LEFT COLUMN: Controls & Inputs */}
          <div className="lg:col-span-5 flex flex-col gap-8">

            {/* Step 1: Uploads */}
            <div className="space-y-6 bg-gray-900/50 p-6 rounded-2xl border border-gray-800">
              <h2 className="text-lg font-semibold flex items-center gap-2">
                <span className="w-6 h-6 rounded-full bg-gray-800 text-gray-400 text-xs flex items-center justify-center border border-gray-700">1</span>
                Upload Assets
              </h2>

              <ImageUpload 
                label="Product Images (Subjects)" 
                images={productImages}
                onImagesAdded={handleProductImagesAdded}
                onImageRemoved={handleProductImageRemoved}
                heightClass="h-56"
                placeholderText="Upload product shots"
              />

              <div className="pt-2 border-t border-gray-800/50">
                <div className="flex justify-between items-center mb-2">
                  <label className="text-sm font-medium text-gray-300">
                    {mode === 'ON' ? 'Style References (Optional)' : 'Scene Backgrounds (Optional)'}
                  </label>
                  {isAnalyzingStyle && mode === 'ON' && <span className="text-xs text-primary-400 animate-pulse">Analyzing styles...</span>}
                </div>
                <ImageUpload 
                  label=""
                  images={styleImages}
                  onImagesAdded={handleStyleImagesAdded}
                  onImageRemoved={handleStyleImageRemoved}
                  placeholderText={mode === 'ON' ? "Upload vibes" : "Upload scenes"}
                  heightClass="h-24"
                />
              </div>
            </div>

            {/* Step 2: Settings */}
            <div className="space-y-6 bg-gray-900/50 p-6 rounded-2xl border border-gray-800">
              <h2 className="text-lg font-semibold flex items-center gap-2">
                 <span className="w-6 h-6 rounded-full bg-gray-800 text-gray-400 text-xs flex items-center justify-center border border-gray-700">2</span>
                Configuration
              </h2>
              <Controls 
                aspectRatio={aspectRatio} setAspectRatio={setAspectRatio}
                lighting={lighting} setLighting={setLighting}
                perspective={perspective} setPerspective={setPerspective}
                mode={mode} setMode={setMode}
              />
            </div>

            {/* Step 3: Prompt */}
            <div className="space-y-4 bg-gray-900/50 p-6 rounded-2xl border border-gray-800">
              <h2 className="text-lg font-semibold flex items-center gap-2">
                 <span className="w-6 h-6 rounded-full bg-gray-800 text-gray-400 text-xs flex items-center justify-center border border-gray-700">3</span>
                {mode === 'ON' ? 'Generated Prompt & Rules' : 'Manual Prompt'}
              </h2>
              <p className="text-xs text-gray-400">
                {mode === 'ON' 
                  ? "This is the single source of truth for generation, including analysis and strict foundation rules."
                  : "Enter instructions for the scene replacement, or leave empty for auto-composition."
                }
              </p>
              <textarea
                value={prompt}
                onChange={(e) => setPrompt(e.target.value)}
                className="w-full h-80 bg-gray-950 border border-gray-700 rounded-lg p-4 text-xs text-gray-200 focus:ring-1 focus:ring-primary-500 focus:border-primary-500 resize-none font-mono leading-relaxed"
                placeholder={mode === 'ON' ? "Analysis and Rules will appear here..." : "e.g., Place the products on the wooden table..."}
              />
            </div>

            {/* Action */}
            <button
              onClick={handleGenerate}
              disabled={productImages.length === 0 || isGenerating || isAnalyzingStyle}
              className={`
                sticky bottom-6 z-40 w-full py-4 px-6 rounded-xl font-bold text-lg shadow-lg transition-all transform active:scale-[0.98]
                flex items-center justify-center gap-3
                ${productImages.length === 0 || isGenerating || isAnalyzingStyle
                  ? 'bg-gray-800 text-gray-500 cursor-not-allowed' 
                  : 'bg-gradient-to-r from-primary-600 to-primary-500 hover:from-primary-500 hover:to-primary-400 text-white shadow-primary-900/20'
                }
              `}
            >
              {isGenerating ? (
                <>
                  <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                  </svg>
                  Processing...
                </>
              ) : (
                <>
                  <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" className="w-5 h-5">
                    <path fillRule="evenodd" d="M9.315 7.584C12.195 3.883 16.695 1.5 21.75 1.5a.75.75 0 0 1 .75.75c0 5.056-2.383 9.555-6.084 12.436h.001c-3.3 2.567-6.93 2.567-9.691 2.567H3.25C1.83 17.253.375 18.064.375 20.25a.75.75 0 0 0 .75.75h21.75a.75.75 0 0 0 .75-.75c0-2.186-1.455-2.997-2.875-2.997H16.19c-2.76 0-6.39 0-9.69-2.567C2.882 11.952.5 7.452.5 2.396a.75.75 0 0 1 .75-.75c5.055 0 9.555 2.383 12.436 6.084l-3.375 3.375-3.001-3.52Z" clipRule="evenodd" />
                  </svg>
                  Generate Image
                </>
              )}
            </button>
            {error && (
              <div className="p-4 bg-red-900/20 border border-red-800 text-red-200 rounded-lg text-sm">
                {error}
              </div>
            )}
          </div>

          {/* RIGHT COLUMN: Output */}
          <div className="lg:col-span-7 flex flex-col gap-6">
            <div className="bg-gray-900/50 border border-gray-800 rounded-2xl p-2 h-[600px] flex flex-col relative overflow-hidden group">
              <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-20 pointer-events-none"></div>

              {generatedImage ? (
                <div className="relative w-full h-full flex items-center justify-center bg-black rounded-xl overflow-hidden group/image">
                   <img 
                    src={generatedImage} 
                    alt="Generated Product" 
                    className="max-w-full max-h-full object-contain shadow-2xl cursor-zoom-in transition-transform duration-300 group-hover/image:scale-[1.01]"
                    onClick={() => setIsLightboxOpen(true)}
                  />
                  <a 
                    href={generatedImage} 
                    download="nanostudio-edit.png"
                    className="absolute top-4 right-4 bg-black/50 hover:bg-black/70 backdrop-blur-md text-white px-4 py-2 rounded-full text-sm font-medium transition-colors border border-white/10 flex items-center gap-2 z-10"
                    onClick={(e) => e.stopPropagation()}
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4">
                      <path strokeLinecap="round" strokeLinejoin="round" d="M3 16.5v2.25A2.25 2.25 0 0 0 5.25 21h13.5A2.25 2.25 0 0 0 21 18.75V16.5M12 9.75v10.5m0 0L7.5 15.75M12 20.25l4.5-4.5M12 3v9" />
                    </svg>
                    Download
                  </a>
                  <div className="absolute bottom-4 left-1/2 -translate-x-1/2 opacity-0 group-hover/image:opacity-100 transition-opacity bg-black/50 backdrop-blur-md px-3 py-1 rounded-full text-xs text-white/80 pointer-events-none">
                    Click to enlarge
                  </div>
                </div>
              ) : (
                <div className="w-full h-full flex flex-col items-center justify-center text-gray-600 gap-4 bg-gray-950/50 rounded-xl">
                  {isGenerating ? (
                    <div className="flex flex-col items-center gap-4 animate-pulse">
                      <div className="w-16 h-16 rounded-full bg-gray-800"></div>
                      <div className="h-4 w-32 bg-gray-800 rounded"></div>
                    </div>
                  ) : (
                    <>
                      <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1} stroke="currentColor" className="w-24 h-24 opacity-20">
                        <path strokeLinecap="round" strokeLinejoin="round" d="m2.25 15.75 5.159-5.159a2.25 2.25 0 0 1 3.182 0l5.159 5.159m-1.5-1.5 1.409-1.409a2.25 2.25 0 0 1 3.182 0l2.909 2.909m-18 3.75h16.5a1.5 1.5 0 0 0 1.5-1.5V6a1.5 1.5 0 0 0-1.5-1.5H3.75A1.5 1.5 0 0 0 2.25 6v12a1.5 1.5 0 0 0 1.5 1.5Zm10.5-11.25h.008v.008h-.008V8.25Zm.375 0a.375.375 0 1 1-.75 0 .375.375 0 0 1 .75 0Z" />
                      </svg>
                      <p className="text-gray-500">Result will appear here</p>
                    </>
                  )}
                </div>
              )}
            </div>

            {/* History Section */}
            {history.length > 0 && (
              <div className="bg-gray-900/50 border border-gray-800 rounded-2xl p-6">
                <div className="flex items-center justify-between mb-4">
                  <h3 className="text-sm font-semibold text-gray-400 uppercase tracking-wider">Recent Generations</h3>
                  <button 
                    onClick={() => setHistory([])}
                    className="text-xs text-gray-500 hover:text-red-400 transition-colors"
                  >
                    Clear History
                  </button>
                </div>
                <div className="flex gap-4 overflow-x-auto pb-2 scrollbar-thin scrollbar-thumb-gray-700 scrollbar-track-transparent">
                  {history.map(item => (
                    <button
                      key={item.id}
                      onClick={() => setGeneratedImage(item.imageUrl)}
                      className={`relative flex-shrink-0 w-24 h-24 rounded-lg overflow-hidden border-2 transition-all group ${
                        generatedImage === item.imageUrl 
                          ? 'border-primary-500 ring-2 ring-primary-500/20' 
                          : 'border-transparent hover:border-gray-600'
                      }`}
                    >
                      <img 
                        src={item.imageUrl} 
                        alt="History item" 
                        className="w-full h-full object-cover" 
                      />
                      <div className="absolute inset-0 bg-black/0 group-hover:bg-black/10 transition-colors" />
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>
      </main>

      {/* Lightbox Overlay */}
      {isLightboxOpen && generatedImage && (
        <div 
          className="fixed inset-0 z-[100] flex items-center justify-center bg-black/95 backdrop-blur-md p-4 animate-in fade-in duration-200"
          onClick={() => setIsLightboxOpen(false)}
        >
          {/* Close Button */}
          <button 
            className="absolute top-6 right-6 text-gray-400 hover:text-white transition-colors bg-gray-900/50 rounded-full p-2 hover:bg-gray-800 border border-white/10 z-50"
            onClick={(e) => {
              e.stopPropagation();
              setIsLightboxOpen(false);
            }}
          >
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-8 h-8">
              <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>

          <img 
            src={generatedImage} 
            alt="Full Resolution Result" 
            className="max-w-full max-h-full object-contain shadow-2xl rounded-sm"
            onClick={(e) => e.stopPropagation()}
          />
        </div>
      )}
    </div>
  );
};

export default App;

import { GoogleGenAI } from "@google/genai";

// Initialize the client
// Using process.env.API_KEY as per instructions
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Analyzes style reference images to extract descriptive keywords.
 * Uses a text model (Gemini 3 Flash) for analysis.
 * Accepts multiple images.
 */
export const analyzeStyleReference = async (imagesBase64: string[]): Promise<string> => {
  if (imagesBase64.length === 0) return "";

  try {
    const parts: any[] = [];

    // Add all images as parts
    imagesBase64.forEach(base64 => {
      // Clean base64 just in case, though usually handled by caller
      const cleanBase64 = base64.includes(',') ? base64.split(',')[1] : base64;
      parts.push({
        inlineData: {
          mimeType: 'image/jpeg',
          data: cleanBase64
        }
      });
    });

    parts.push({
      text: `Perform a deep visual analysis of the provided reference image(s) to assist in generating a new product photo.

Focus specifically on these aspects:
1. **Lighting**: Analyze the direction, hardness/softness, color temperature, and shadow density.
2. **Colors & Mood**: Identify the dominant color palette, saturation levels, grading style, and emotional tone.
3. **Camera & Perspective**: Determine the camera angle, focal length characteristics, and depth of field (bokeh vs deep focus).
4. **Composition & Realism**: Analyze the texture rendering, negative space usage, and level of photorealism.

**CRITICAL INSTRUCTION FOR MULTIPLE IMAGES:**
If multiple reference images are provided, do NOT describe them individually. Instead, intelligently MERGE the strongest and most compatible aesthetic elements from each image to define a SINGLE, COHESIVE visual style. Create a description for a unique, new look that blends these influences seamlessly without directly replicating any specific scene or object from the references.

Output a highly detailed, coherent paragraph describing this synthesized visual style. Do NOT mention specific objects (like "a bottle" or "shoes") found in the references; focus exclusively on the photographic and artistic qualities.`
    });

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts }
    });

    return response.text || "";
  } catch (error) {
    console.error("Error analyzing style reference:", error);
    return "High quality, professional photography with excellent lighting and composition."; // Fallback
  }
};

/**
 * Generates the edited product image using Nano Banana (gemini-2.5-flash-image).
 * Supports arrays of product images and optional reference images.
 * Uses the exact prompt string provided by the caller (which now includes all system rules).
 */
export const generateEditedImage = async (
  productImagesBase64: string[],
  prompt: string,
  aspectRatio: string,
  referenceImagesBase64: string[] = []
): Promise<string> => {
  try {
    const parts: any[] = [];

    // Add Product Images
    productImagesBase64.forEach(base64 => {
      const cleanBase64 = base64.includes(',') ? base64.split(',')[1] : base64;
      parts.push({
        inlineData: {
          mimeType: 'image/jpeg',
          data: cleanBase64,
        },
      });
    });

    // Add Reference Images (if any)
    referenceImagesBase64.forEach(base64 => {
      const cleanBase64 = base64.includes(',') ? base64.split(',')[1] : base64;
      parts.push({
        inlineData: {
          mimeType: 'image/jpeg',
          data: cleanBase64,
        },
      });
    });

    // Add the text prompt last
    parts.push({ text: prompt });

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image', // Nano Banana
      contents: { parts },
      config: {
        imageConfig: {
          aspectRatio: aspectRatio,
        },
      },
    });

    // Check for inline data (the image)
    // The response candidates usually contain the image part
    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }

    throw new Error("No image data found in response");

  } catch (error) {
    console.error("Error generating image:", error);
    throw error;
  }
};

/**
 * Helper to convert Blob/File to Base64 string (without data prefix for API usage if needed, 
 * but @google/genai usually takes raw base64).
 * We will return the raw base64 string.
 */
export const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => {
      const result = reader.result as string;
      // Remove the data URL prefix (e.g., "data:image/jpeg;base64,")
      const base64 = result.split(',')[1];
      resolve(base64);
    };
    reader.onerror = (error) => reject(error);
  });
};

