import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisResult } from "../types";

/**
 * Analyzes style reference images (or product images) to extract descriptive keywords and infer settings.
 * Uses a text model (Gemini 3 Flash) with JSON schema output.
 * Accepts multiple images.
 */
export const analyzeStyleReference = async (imagesBase64: string[]): Promise<AnalysisResult> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  if (imagesBase64.length === 0) {
    return {
      description: "",
      recommendedAspectRatio: "1:1",
      recommendedLighting: "Studio Lighting",
      recommendedPerspective: "Eye Level"
    };
  }

  try {
    const parts: any[] = [];

    // Add all images as parts
    imagesBase64.forEach(base64 => {
      // Clean base64 just in case
      const cleanBase64 = base64.includes(',') ? base64.split(',')[1] : base64;
      parts.push({
        inlineData: {
          mimeType: 'image/jpeg',
          data: cleanBase64
        }
      });
    });

    parts.push({
      text: `Analyze the provided images to create a professional photographer's brief.

      1. Create a detailed visual description of the style, mood, and environment.
      2. Analyze the ACTUAL lighting technique and camera perspective used in the image.

      CRITICAL INSTRUCTION FOR technical settings:
      - Do NOT limit yourself to standard presets.
      - If the lighting or perspective is unique, specific, or complex, use a descriptive phrase that accurately matches the image (e.g. "Rembrandt Lighting with Blue Rim", "Low Angle Fish-Eye", "Hard Flash with defined shadows").
      - Only use standard terms (like "Studio Lighting" or "Eye Level") if they are an EXACT match.
      - Your goal is to extract the REAL technical attributes of the reference image.`
    });

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            description: { 
              type: Type.STRING, 
              description: "A highly detailed, coherent paragraph describing the visual style, lighting, mood, and composition for a generated image." 
            },
            recommendedAspectRatio: { 
              type: Type.STRING, 
              enum: ["1:1", "3:4", "4:3", "9:16", "16:9"],
              description: "The optimal aspect ratio."
            },
            recommendedLighting: { 
              type: Type.STRING, 
              description: "The matching lighting style. Can be a standard term or a custom descriptive phrase."
            },
            recommendedPerspective: { 
              type: Type.STRING, 
              description: "The matching camera perspective. Can be a standard term or a custom descriptive phrase."
            }
          },
          required: ["description", "recommendedAspectRatio", "recommendedLighting", "recommendedPerspective"]
        }
      }
    });

    const text = response.text;
    if (!text) {
       throw new Error("No text response from analysis");
    }

    const json = JSON.parse(text);

    return {
      description: json.description || "",
      recommendedAspectRatio: json.recommendedAspectRatio || "1:1",
      recommendedLighting: json.recommendedLighting || "Studio Lighting",
      recommendedPerspective: json.recommendedPerspective || "Eye Level"
    };

  } catch (error) {
    console.error("Error analyzing style reference:", error);
    return {
      description: "High quality, professional photography with excellent lighting and composition.",
      recommendedAspectRatio: "1:1",
      recommendedLighting: "Studio Lighting",
      recommendedPerspective: "Eye Level"
    };
  }
};

/**
 * Generates the edited product image using Nano Banana (gemini-2.5-flash-image).
 * Supports arrays of product images and optional reference images.
 * Uses the exact prompt string provided by the caller (which now includes all system rules).
 */
export const generateEditedImage = async (
  productImagesBase64: string[],
  prompt: string,
  aspectRatio: string,
  referenceImagesBase64: string[] = []
): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  try {
    const parts: any[] = [];

    // Add Product Images
    productImagesBase64.forEach(base64 => {
      const cleanBase64 = base64.includes(',') ? base64.split(',')[1] : base64;
      parts.push({
        inlineData: {
          mimeType: 'image/jpeg',
          data: cleanBase64,
        },
      });
    });

    // Add Reference Images (if any)
    referenceImagesBase64.forEach(base64 => {
      const cleanBase64 = base64.includes(',') ? base64.split(',')[1] : base64;
      parts.push({
        inlineData: {
          mimeType: 'image/jpeg',
          data: cleanBase64,
        },
      });
    });

    // Add the text prompt last
    parts.push({ text: prompt });

    // Ensure aspectRatio is a valid string for the API, defaulting if it's somehow still "Auto" or invalid
    const validAspectRatios = ["1:1", "3:4", "4:3", "9:16", "16:9"];
    const finalAspectRatio = validAspectRatios.includes(aspectRatio) ? aspectRatio : "1:1";

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image', // Nano Banana
      contents: { parts },
      config: {
        imageConfig: {
          aspectRatio: finalAspectRatio,
        },
      },
    });

    // Check for inline data (the image)
    // The response candidates usually contain the image part
    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }

    throw new Error("No image data found in response");

  } catch (error) {
    console.error("Error generating image:", error);
    throw error;
  }
};

/**
 * Upscales an image to 4K resolution using Gemini 3 Pro Image Preview.
 */
export const upscaleImage = async (
  imageBase64: string,
  aspectRatio: string
): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  try {
    const parts: any[] = [];
    const cleanBase64 = imageBase64.includes(',') ? imageBase64.split(',')[1] : imageBase64;

    parts.push({
      inlineData: {
        mimeType: 'image/png',
        data: cleanBase64
      }
    });

    parts.push({ text: "Generate a high-fidelity, 4K resolution version of this image. Preserve all details, composition, lighting, and subjects exactly as they appear in the original image. Significantly improve sharpness and clarity." });

    const validAspectRatios = ["1:1", "3:4", "4:3", "9:16", "16:9"];
    const finalAspectRatio = validAspectRatios.includes(aspectRatio) ? aspectRatio : "1:1";

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: { parts },
      config: {
        imageConfig: {
          aspectRatio: finalAspectRatio,
          imageSize: '4K'
        }
      }
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
    throw new Error("No image data found in upscale response");

  } catch (error) {
    console.error("Error upscaling image:", error);
    throw error;
  }
};

/**
 * Helper to convert Blob/File to Base64 string.
 */
export const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => {
      const result = reader.result as string;
      // Remove the data URL prefix (e.g., "data:image/jpeg;base64,")
      const base64 = result.split(',')[1];
      resolve(base64);
    };
    reader.onerror = (error) => reject(error);
  });
};

import React, { useState, useEffect, useCallback } from 'react';
import { ImageUpload } from './components/ImageUpload';
import { Controls } from './components/Controls';
import { AspectRatio, LightingStyle, CameraPerspective, HistoryItem, UploadedImage } from './types';
import { analyzeStyleReference, generateEditedImage, upscaleImage, fileToBase64 } from './services/geminiService';

const App: React.FC = () => {
  // Mode State: ON = Auto/Creative, OFF = Manual/Scene Preservation
  const [mode, setMode] = useState<'ON' | 'OFF'>('ON');

  // State for Inputs (Arrays)
  const [productImages, setProductImages] = useState<UploadedImage[]>([]);
  const [styleImages, setStyleImages] = useState<UploadedImage[]>([]);

  const [styleDescription, setStyleDescription] = useState<string>("");
  const [isAnalyzingStyle, setIsAnalyzingStyle] = useState<boolean>(false);

  // State for Controls - Defaulting to AUTO
  const [aspectRatio, setAspectRatio] = useState<AspectRatio>(AspectRatio.AUTO);
  const [lighting, setLighting] = useState<LightingStyle>(LightingStyle.AUTO);
  const [perspective, setPerspective] = useState<CameraPerspective>(CameraPerspective.AUTO);

