                onClick={handleGenerate}
                disabled={productImages.length === 0 || isGenerating || isAnalyzingStyle || isUpscaling}
                className={`
                  relative w-full py-4 px-6 rounded-xl font-bold text-lg transition-all duration-300 transform active:scale-[0.98]
                  flex items-center justify-center gap-3 border
                  ${productImages.length === 0 || isGenerating || isAnalyzingStyle || isUpscaling
                    ? 'bg-gray-900 border-gray-800 text-gray-500 cursor-not-allowed' 
                    : 'bg-black border-transparent text-white shadow-2xl'
                  }
                `}
              >
                {isGenerating ? (
                  <>
                    <svg className="animate-spin -ml-1 mr-3 h-5 w-5" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                      <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                      <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                    </svg>
                    Processing...
                  </>
                ) : (
                  <>
                    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" className="w-5 h-5 text-white">
                      <path fillRule="evenodd" d="M9.315 7.584C12.195 3.883 16.695 1.5 21.75 1.5a.75.75 0 0 1 .75.75c0 5.056-2.383 9.555-6.084 12.436h.001c-3.3 2.567-6.93 2.567-9.691 2.567H3.25C1.83 17.253.375 18.064.375 20.25a.75.75 0 0 0 .75.75h21.75a.75.75 0 0 0 .75-.75c0-2.186-1.455-2.997-2.875-2.997H16.19c-2.76 0-6.39 0-9.69-2.567C2.882 11.952.5 7.452.5 2.396a.75.75 0 0 1 .75-.75c5.055 0 9.555 2.383 12.436 6.084l-3.375 3.375-3.001-3.52Z" clipRule="evenodd" />
                    </svg>
                    <span className="text-white drop-shadow-[0_0_10px_rgba(255,255,255,0.7)]">
                      Generate Image
                    </span>
                  </>
                )}
              </button>
            </div>

            {error && (
              <div className="p-4 bg-gray-900 border border-white text-white rounded-lg text-sm">
                {error}
              </div>
            )}

            {/* History Section */}
            {history.length > 0 && (
              <div className="bg-gray-900 border border-gray-800 rounded-2xl p-6">
                <div className="flex items-center justify-between mb-4">
                  <h3 className="text-sm font-semibold text-gray-500 uppercase tracking-wider">Recent Generations</h3>
                  <button 
                    onClick={() => setHistory([])}
                    className="text-xs text-gray-500 hover:text-white transition-colors"
                  >
                    Clear History
                  </button>
                </div>
                <div className="flex gap-4 overflow-x-auto pb-2 scrollbar-thin scrollbar-thumb-gray-800 scrollbar-track-transparent">
                  {history.map(item => (
                    <button
                      key={item.id}
                      onClick={() => setGeneratedImage(item.imageUrl)}
                      className={`relative flex-shrink-0 w-24 h-24 rounded-lg overflow-hidden border-2 transition-all group ${
                        generatedImage === item.imageUrl 
                          ? 'border-white ring-2 ring-white/20' 
                          : 'border-transparent hover:border-gray-600'
                      }`}
                    >
                      <img 
                        src={item.imageUrl} 
                        alt="History item" 
                        className="w-full h-full object-cover" 
                      />
                      <div className="absolute inset-0 bg-black/0 group-hover:bg-black/10 transition-colors" />
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>
      </main>

      {/* Lightbox Overlay */}
      {isLightboxOpen && generatedImage && (
        <div 
          className="fixed inset-0 z-[100] flex items-center justify-center bg-black/95 backdrop-blur-md p-4 animate-in fade-in duration-200"
          onClick={() => setIsLightboxOpen(false)}
        >
          {/* Close Button */}
          <button 
            className="absolute top-6 right-6 text-gray-400 hover:text-white transition-colors bg-gray-900 rounded-full p-2 hover:bg-gray-800 border border-gray-800 z-50"
            onClick={(e) => {
              e.stopPropagation();
              setIsLightboxOpen(false);
            }}
          >
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-8 h-8">
              <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>

          <img 
            src={generatedImage} 
            alt="Full Resolution Result" 
            className="max-w-full max-h-full object-contain shadow-2xl rounded-sm border border-gray-800"
            onClick={(e) => e.stopPropagation()}
          />
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback } from 'react';
import { ImageUpload } from './components/ImageUpload';
import { Controls } from './components/Controls';
import { AspectRatio, LightingStyle, CameraPerspective, HistoryItem, UploadedImage } from './types';
import { analyzeStyleReference, generateEditedImage, upscaleImage, fileToBase64 } from './services/geminiService';

const App: React.FC = () => {
  // Mode State: ON = Auto/Creative, BOARD = Campaign Grid, OFF = Manual/Scene Preservation
  const [mode, setMode] = useState<'ON' | 'OFF' | 'BOARD'>('ON');

  // State for Inputs (Arrays)
  const [productImages, setProductImages] = useState<UploadedImage[]>([]);
  const [styleImages, setStyleImages] = useState<UploadedImage[]>([]);

  const [styleDescription, setStyleDescription] = useState<string>("");
  const [isAnalyzingStyle, setIsAnalyzingStyle] = useState<boolean>(false);

  // State for Controls - Defaulting to AUTO
  const [aspectRatio, setAspectRatio] = useState<AspectRatio>(AspectRatio.AUTO);
  const [lighting, setLighting] = useState<LightingStyle>(LightingStyle.AUTO);
  const [perspective, setPerspective] = useState<CameraPerspective>(CameraPerspective.AUTO);

  // State for Custom Inferred Values (when Auto is selected but analysis finds a custom value)
  const [inferredLighting, setInferredLighting] = useState<string | null>(null);
  const [inferredPerspective, setInferredPerspective] = useState<string | null>(null);

  // State for Prompt
  const [prompt, setPrompt] = useState<string>("");

  // State for Generation
  const [isGenerating, setIsGenerating] = useState<boolean>(false);
  const [generatedImage, setGeneratedImage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  // State for Upscaling
  const [isUpscaling, setIsUpscaling] = useState<boolean>(false);
  const [showDownloadMenu, setShowDownloadMenu] = useState<boolean>(false);

  // State for Lightbox
  const [isLightboxOpen, setIsLightboxOpen] = useState<boolean>(false);

  // State for History
  const [history, setHistory] = useState<HistoryItem[]>([]);

  // Update prompt whenever controls or style description changes (IN ON and BOARD MODE)
  useEffect(() => {
    if (mode === 'OFF') return;

    // 1. Analysis Section
    let analysisSection = "";
    if (styleDescription) {
      // Build string for inferred values if they exist
      const inferredLightText = inferredLighting ? `Inferred Lighting: ${inferredLighting}` : "";
      const inferredCamText = inferredPerspective ? `Inferred Angle:    ${inferredPerspective}` : "";
      const inferenceDetails = [inferredLightText, inferredCamText].filter(Boolean).join('\n');

      analysisSection = `[ STYLE ANALYSIS & INFERENCE ]
----------------------------------------------------------------------
${styleDescription}
${inferenceDetails ? `\n${inferenceDetails}\n` : ''}
`;
    }

    // Determine values to show in prompt (Fallbacks if AUTO is still selected for some reason)
    const activeLighting = lighting === LightingStyle.AUTO 
      ? (inferredLighting ? `${inferredLighting} (Inferred)` : "Studio Lighting (Default)")
      : lighting;

    const activePerspective = perspective === CameraPerspective.AUTO 
      ? (inferredPerspective ? `${inferredPerspective} (Inferred)` : "Eye Level (Default)")
      : perspective;

    // GLOBAL SIZE POLICY: Auto = 1:1
    const activeAspectRatio = aspectRatio === AspectRatio.AUTO 
      ? "1:1 (Default)" 
      : aspectRatio;

    let operationalRules = "";

    if (mode === 'BOARD') {
      // --- BOARD MODE RULES (SEMANTIC CAMPAIGN) ---
      operationalRules = `[ BOARD MODE: SEMANTIC CAMPAIGN GENERATION ]
----------------------------------------------------------------------
SYSTEM INSTRUCTION: Generate a SINGLE high-resolution image containing EXACTLY 6 distinct product shots arranged in a clean, unified grid (e.g. 2x3 or 3x2).

[ GENERATION TYPE: SEMANTIC SCENE ENFORCEMENT ]
Before generation, split the request into 6 independent semantic visual scenes.
Do NOT vary based on camera angle only.

[ SEMANTIC DIFFERENTIATION ]
Each scene must differ at a conceptual level in:
1. Visual idea
2. Mood
3. Product role within the scene
4. Product-to-space relationship

[ MANDATORY SCENE SEPARATION RULE ]
Two scenes may NOT share the same visual meaning, even if camera angle, crop, or distance are different.
Any semantic similarity is considered invalid duplication.

[ ENFORCED EXECUTION LOGIC ]
1. Extract multiple visual concepts from the Style Analysis.
2. Select 6 semantically unique scenes with ZERO overlap.
3. Assign one frame per scene only.
4. Compare each scene against others based on concept, mood, and usage.
5. If similarity is detected → discard and regenerate with a fundamentally different idea.

[ MAXIMUM ANTI-REPETITION RULES ]
FORBIDDEN:
- Same product posture
- Same spatial relationship
- Same emotional tone
- Background or angle changes do NOT qualify as true variation.

[ FINAL OUTPUT REQUIREMENT ]
- Each scene must feel like it belongs to a different conceptual idea.
- Visually cohesive as a campaign, but conceptually distinct.
- Any output that looks like a variation is considered generation failure.

[ TECHNICAL CONFIGURATION ]
• Lighting: ${activeLighting}
• Aspect Ratio: ${activeAspectRatio}
• No text or watermarks.`;

    } else {
      // --- ON MODE (SMART CREATIVE) RULES ---
      operationalRules = `[ SYSTEM OPERATIONAL FOUNDATION ]
----------------------------------------------------------------------
[ MODE: ON - REFERENCE-BASED PROFESSIONAL ADAPTATION ]

[ PRODUCT SOURCE AUTHORITY - ABSOLUTE ]
• The uploaded Product Image is the ONLY valid source for the product's appearance.
• Do NOT replace or swap the product under any condition.
• The product must always be the current active product.
• If a product appears in the Reference Image, IGNORE IT COMPLETELY.

[ REFERENCE IMAGE USAGE POLICY ]
• Use the Reference Image strictly as a source for:
  - Overall composition logic
  - Lighting
  - Mood
  - Visual style

• STRICTLY FORBIDDEN:
  - Exact replication of the reference scene.
  - Recreating the same composition, camera angle, or element layout.

[ EXECUTION LOGIC: PROFESSIONAL ADAPTATION ]
1. ANALYZE the reference to extract its composition principles, lighting behavior, depth, and emotional tone.
2. REBUILD a new scene that is:
   - Inspired by the reference.
   - But with a DIFFERENT composition.
   - DIFFERENT camera angle.
   - NEW spatial arrangement.
3. INTEGRATE the product into the new scene professionally and realistically, matching the reference's lighting and style.

[ ANTI-COPY ENFORCEMENT ]
• Any output that matches the reference in Scene, Composition, or Camera angle is considered EXECUTION FAILURE and must be regenerated.

[ REQUIRED OUTCOME ]
• A result that is MORE polished and professional than the reference.
• Same visual spirit, but new and original execution.
• Improved realism, balance, and final presentation without direct imitation.

[ TECHNICAL CONFIGURATION ]
----------------------------------------------------------------------
Lighting Style:   ${activeLighting}
Camera Angle:     ${activePerspective}
Aspect Ratio:     ${activeAspectRatio}

[ STRICT NEGATIVE CONSTRAINTS ]
----------------------------------------------------------------------
• STRICT REQUIREMENT: The final generated image must be completely free of text, writing, logos, symbols, and watermarks.
• TEXT BAN: Ensure NO letters, NO characters, and NO written language appear anywhere in the scene.
• CRITICAL: Preserve the final output dimensions with NO empty white areas.
• Extend the scene naturally to fill the ENTIRE frame.

[ SUBJECT INTEGRITY ]
----------------------------------------------------------------------
• Use ONLY the ${productImages.length} uploaded product(s).
• Treat each product image as a fixed visual object. Keep packaging design, logo, and colors exact.`;
    }

    // Combine them
    setPrompt(`${analysisSection}${operationalRules}`);

  }, [lighting, perspective, aspectRatio, productImages.length, styleDescription, mode, inferredLighting, inferredPerspective]);

  // When Mode switches to OFF, clear the auto-generated prompt if user hasn't typed
  useEffect(() => {
    if (mode === 'OFF') {
      setPrompt("");
    } else {
      // Trigger prompt regeneration by touching state
      setPerspective(prev => prev); 
      // If we have any images but controls are AUTO, triggering analysis might be good
      if ((styleImages.length > 0 || productImages.length > 0) && !styleDescription) {
        // Decide what to analyze based on priority
        const imagesToAnalyze = styleImages.length > 0 ? styleImages : productImages;
        analyzeStyles(imagesToAnalyze);
      }
    }
  }, [mode]);

  // Helper to extract clean base64s from UploadedImage array
  const getCleanBase64s = (images: UploadedImage[]) => {
    return images.map(img => img.base64.split(',')[1]);
  };

  const analyzeStyles = async (images: UploadedImage[]) => {
    if (images.length === 0) return;

    setIsAnalyzingStyle(true);
    try {
      const base64s = getCleanBase64s(images);
      const result = await analyzeStyleReference(base64s);

      setStyleDescription(result.description);

      // ASPECT RATIO
      // STRICT POLICY: Auto is locked to 1:1. 
      // Analysis recommendations for size are intentionally ignored to enforce the Global Size Policy.

      // LIGHTING
      // If currently Auto, try to map to enum OR use custom inferred string
      if (lighting === LightingStyle.AUTO) {
        const lightingValues = Object.values(LightingStyle) as string[];
        if (lightingValues.includes(result.recommendedLighting)) {
          // Exact match found in Enums
          setLighting(result.recommendedLighting as LightingStyle);
          setInferredLighting(null);
        } else {
          // No match, it's a custom description
          setInferredLighting(result.recommendedLighting);
          // Keep state as Auto so dropdown shows "Auto"
        }
      }

      // PERSPECTIVE
      // If currently Auto, try to map to enum OR use custom inferred string
      if (perspective === CameraPerspective.AUTO) {
        const perspectiveValues = Object.values(CameraPerspective) as string[];
        if (perspectiveValues.includes(result.recommendedPerspective)) {
          // Exact match found in Enums
          setPerspective(result.recommendedPerspective as CameraPerspective);
          setInferredPerspective(null);
        } else {
          // No match, it's a custom description
          setInferredPerspective(result.recommendedPerspective);
          // Keep state as Auto so dropdown shows "Auto"
        }
      }

    } catch (err) {
      console.error(err);
      setError("Failed to analyze style reference images.");
    } finally {
      setIsAnalyzingStyle(false);
    }
  };

  const handleReAnalyze = () => {
    if (mode === 'OFF' || isAnalyzingStyle) return;

    // Determine what to analyze based on current uploads
    // Prioritize style images if present, otherwise analyze product images
    const imagesToAnalyze = styleImages.length > 0 ? styleImages : productImages;

    if (imagesToAnalyze.length > 0) {
      analyzeStyles(imagesToAnalyze);
    }
  };

  // Handle Style Image Updates
  const handleStyleImagesAdded = (newImages: UploadedImage[]) => {
    const updated = [...styleImages, ...newImages];
    setStyleImages(updated);

    // Only analyze if in ON or BOARD mode
    if (mode !== 'OFF') {
      // Prioritize style images for analysis
      analyzeStyles(updated);
    } else {
      setStyleDescription("");
    }
  };

  const handleStyleImageRemoved = (id: string) => {
    const updated = styleImages.filter(img => img.id !== id);
    setStyleImages(updated);

    if (mode !== 'OFF') {
        if (updated.length > 0) {
            analyzeStyles(updated);
        } else if (productImages.length > 0) {
            // Fallback to analyzing product images if style references are gone
            analyzeStyles(productImages);
        } else {
            setStyleDescription("");
        }
    } else if (updated.length === 0) {
      setStyleDescription("");
    }
  };

  // Handle Product Image Updates
  const handleProductImagesAdded = (newImages: UploadedImage[]) => {
    const updated = [...productImages, ...newImages];
    setProductImages(updated);
    // Reset generation when new product uploaded
    setGeneratedImage(null);
    setShowDownloadMenu(false);

    // If in ON/BOARD mode and no style images, analyze the product images to infer settings
    if (mode !== 'OFF' && styleImages.length === 0) {
        analyzeStyles(updated);
    }
  };

  const handleProductImageRemoved = (id: string) => {
    const updated = productImages.filter(img => img.id !== id);
    setProductImages(updated);
    if (mode !== 'OFF' && styleImages.length === 0 && updated.length > 0) {
         // re-analyze remaining product images? Optional but good for consistency
    }
  };

  const handleGenerate = async () => {
    if (productImages.length === 0) {
      setError("Please upload at least one product image.");
      return;
    }

    setIsGenerating(true);
    setError(null);
    setGeneratedImage(null);
    setShowDownloadMenu(false);

    try {
      const productBase64s = getCleanBase64s(productImages);
      let referenceBase64s: string[] = [];
      let finalPrompt = prompt;

      // STRICT RESOLUTION OF ASPECT RATIO
      // If Auto, force 1:1. No adaptation to content allowed.
      let effectiveAspectRatio: string = aspectRatio;
      if (aspectRatio === AspectRatio.AUTO) {
        effectiveAspectRatio = "1:1";
      }

      if (mode === 'OFF') {
        // SCENE PRESERVATION MODE
        if (styleImages.length > 0) {
          referenceBase64s = getCleanBase64s(styleImages);

          // STRICT REPLACEMENT LOGIC
          const preservationRules = `[ STRICT SCENE PRESERVATION & PRODUCT REPLACEMENT ]
----------------------------------------------------------------------
SYSTEM INSTRUCTION: You are an expert photo editor performing a precise product replacement.

INPUT DATA:
- Reference Scene: The source image providing the environment, lighting, and composition.
- Uploaded Product: The new subject to be placed into the scene.

[ PRODUCT SOURCE AUTHORITY - ABSOLUTE ]
• The uploaded Product Image is the ONLY valid source for the product's appearance.
• The product shown in the Reference Scene MUST BE REPLACED.
• Do NOT use, recreate, or blend the product from the Reference Scene into the output.
• The final image must feature the Uploaded Product with exact shape, identity, and design.

MANDATORY EXECUTION RULES:
1. SCENE ANALYSIS: Analyze the Reference Scene to identify the exact position, scale, and lighting of the existing subject.
2. REPLACEMENT: Replace the existing subject with the Uploaded Product.
3. COMPOSITION INTEGRITY:
   - Do NOT change the camera angle, focal length, or scene arrangement.
   - The background and surrounding elements must remain IDENTICAL.
   - Do NOT crop the scene.
4. VISUAL MATCHING:
   - Match the lighting direction, intensity, and color temperature of the Reference Scene.
   - Generate realistic shadows and reflections grounded in the scene's geometry.
   - The new product must look like it was originally photographed in this exact scene.

${finalPrompt.trim() ? `USER OVERRIDE/DETAIL: ${finalPrompt}` : ''}`;

          finalPrompt = preservationRules;

        } else if (!finalPrompt.trim()) {
           setError("In Manual mode, please provide a prompt or a scene reference image.");
           setIsGenerating(false);
           return;
        }
      } else {
        // ON and BOARD MODES
        // These modes rely on the useEffect constructed prompt.
        if (!finalPrompt) {
          setError("Generating prompt...");
          return;
        }

        if (mode === 'BOARD' && styleImages.length > 0) {
           referenceBase64s = getCleanBase64s(styleImages);
        } else if (mode === 'ON' && styleImages.length > 0) {
           referenceBase64s = getCleanBase64s(styleImages);
        }
      }

      const resultImageUrl = await generateEditedImage(
        productBase64s, 
        finalPrompt, 
        effectiveAspectRatio, 
        referenceBase64s
      );

      setGeneratedImage(resultImageUrl);

      // Add to history
      setHistory(prev => [
        {
          id: Date.now().toString(),
          imageUrl: resultImageUrl,
          timestamp: Date.now()
        },
        ...prev
      ]);

    } catch (err) {
      console.error(err);
      setError("Failed to generate image. Please try again.");
    } finally {
      setIsGenerating(false);
    }
  };

  // Handle Download Logic
  const handleDownload = async (format: 'png' | 'jpg', resolution: '2K' | '4K') => {
    if (!generatedImage) return;

    // For 4K, we strictly require a paid key and upscaling
    if (resolution === '4K') {
      try {
        // 1. Check/Get API Key using loose typing to avoid conflicts
        const aistudio = (window as any).aistudio;
        if (aistudio) {
          const hasKey = await aistudio.hasSelectedApiKey();
          if (!hasKey) {
             await aistudio.openSelectKey();
             // Race condition logic: assume success and proceed immediately without delay
          }
        }

        setIsUpscaling(true);
        setError(null);

        // 2. Perform Upscaling using internal capabilities (Gemini 3 Pro)
        let upscaleAspectRatio = aspectRatio;
        // STRICT POLICY: Auto = 1:1
        if (aspectRatio === AspectRatio.AUTO) {
           upscaleAspectRatio = AspectRatio.SQUARE; // "1:1"
        }

        const upscaledBase64 = await upscaleImage(generatedImage, upscaleAspectRatio);

        // 3. Download the upscaled result
        downloadImage(upscaledBase64, format, `nanostudio-edit-4k`);

      } catch (err) {
        console.error(err);
        setError("Failed to upscale to 4K. Please try again or use 2K.");
      } finally {
        setIsUpscaling(false);
      }
    } else {
      // For 2K, we download the current image directly (Native resolution) as per instructions
      // "without performing any additional upscaling"
      downloadImage(generatedImage, format, `nanostudio-edit-2k`);
    }
  };

  const downloadImage = (base64Data: string, format: 'png' | 'jpg', filename: string) => {
    const img = new Image();
    img.crossOrigin = "anonymous";
    img.src = base64Data;
    img.onload = () => {
      const canvas = document.createElement('canvas');
      canvas.width = img.width;
      canvas.height = img.height;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        // Fill white background for JPG transparency
        if (format === 'jpg') {
          ctx.fillStyle = '#FFFFFF';
          ctx.fillRect(0, 0, canvas.width, canvas.height);
        }
        ctx.drawImage(img, 0, 0);

        const mimeType = format === 'png' ? 'image/png' : 'image/jpeg';
        const dataUrl = canvas.toDataURL(mimeType, 0.95); // 0.95 quality for JPG

        const link = document.createElement('a');
        link.href = dataUrl;
        link.download = `${filename}.${format}`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
      }
    };
  };

  // Prevent scrolling when lightbox is open
  useEffect(() => {
    if (isLightboxOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
    return () => {
      document.body.style.overflow = 'unset';
    };
  }, [isLightboxOpen]);

  return (
    <div className="min-h-screen bg-gray-950 text-gray-100 font-sans selection:bg-white selection:text-black">
      {/* Custom Keyframes for Animations */}
      <style>{`
        @keyframes rgb-flow {
          0% { background-position: 0% 50%; }
          50% { background-position: 100% 50%; }
          100% { background-position: 0% 50%; }
        }
        .animate-rgb-flow {
          background-size: 400% 400%;
          animation: rgb-flow 3s linear infinite;
        }
        /* DOVE ANIMATION KEYFRAMES */
        @keyframes fly-right {
          0% { transform: translateX(-150%); }
          100% { transform: translateX(250%); }
        }
        @keyframes wing-flap {
          0%, 100% { transform: rotate(0deg) scaleY(1); }
          50% { transform: rotate(-30deg) scaleY(0.8); }
        }
        @keyframes wing-flap-front {
           0%, 100% { transform: rotate(0deg) scaleY(1); }
           50% { transform: rotate(-40deg) scaleY(0.7); }
        }
      `}</style>

      {/* Header */}
      <header className="border-b border-gray-800 bg-gray-950 sticky top-0 z-50">
        <div className="w-full py-4 flex flex-col items-center justify-center">
          <h1 className="text-3xl font-bold text-white tracking-tight mb-1">
            FreeBirdTool
          </h1>
          <span className="text-[10px] text-gray-500 font-medium tracking-wide">
            By the grace of Allah, I was blessed to create this tool.
          </span>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-8">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

          {/* LEFT COLUMN: Controls & Inputs */}
          <div className="lg:col-span-5 flex flex-col gap-8">

            {/* Step 1: Uploads */}
            <div className="space-y-6 bg-gray-900 p-6 rounded-2xl border border-gray-800">
              <h2 className="text-lg font-semibold flex items-center gap-2 text-white">
                <span className="w-6 h-6 rounded-full bg-gray-800 text-gray-500 text-xs flex items-center justify-center border border-gray-700">1</span>
                Upload Assets
              </h2>

              <ImageUpload 
                label="Product Images (Subjects)" 
                images={productImages}
                onImagesAdded={handleProductImagesAdded}
                onImageRemoved={handleProductImageRemoved}
                heightClass="h-56"
                placeholderText="Upload product shots"
              />

              <div className="pt-2 border-t border-gray-800">
                <div className="flex justify-between items-center mb-2">
                  <label className="text-sm font-medium text-gray-300">
                    {mode === 'OFF' ? 'Scene Backgrounds (Optional)' : 'Style References (Optional)'}
                  </label>
                  {isAnalyzingStyle && mode !== 'OFF' && <span className="text-xs text-white animate-pulse">Analyzing & Inferring Settings...</span>}
                </div>
                <ImageUpload 
                  label=""
                  images={styleImages}
                  onImagesAdded={handleStyleImagesAdded}
                  onImageRemoved={handleStyleImageRemoved}
                  placeholderText={mode === 'OFF' ? "Upload scenes" : "Upload vibes"}
                  heightClass="h-24"
                />
              </div>
            </div>

            {/* Step 2: Settings */}
            <div className="space-y-6 bg-gray-900 p-6 rounded-2xl border border-gray-800">
              <h2 className="text-lg font-semibold flex items-center gap-2 text-white">
                 <span className="w-6 h-6 rounded-full bg-gray-800 text-gray-500 text-xs flex items-center justify-center border border-gray-700">2</span>
                Configuration
              </h2>
              <Controls 
                aspectRatio={aspectRatio} setAspectRatio={setAspectRatio}
                lighting={lighting} setLighting={setLighting}
                perspective={perspective} setPerspective={setPerspective}
                mode={mode} setMode={setMode}
              />
            </div>

            {/* Step 3: Prompt */}
            <div className="space-y-4 bg-gray-900 p-6 rounded-2xl border border-gray-800">
              <h2 className="text-lg font-semibold flex items-center gap-2 text-white">
                 <span className="w-6 h-6 rounded-full bg-gray-800 text-gray-500 text-xs flex items-center justify-center border border-gray-700">3</span>
                {mode === 'OFF' ? 'Manual Prompt' : 'Generated Prompt & Rules'}
              </h2>
              <p className="text-xs text-gray-500">
                {mode === 'OFF' 
                  ? "Enter instructions for the scene replacement, or leave empty for auto-composition."
                  : "This is the single source of truth for generation, including analysis and strict foundation rules."
                }
              </p>

              <div className="relative">
                <textarea
                  value={prompt}
                  onChange={(e) => setPrompt(e.target.value)}
                  className="w-full h-80 bg-gray-950 border border-gray-800 rounded-lg p-6 text-sm text-gray-300 focus:ring-1 focus:ring-white focus:border-white resize-none font-sans leading-relaxed tracking-wide"
                  placeholder={mode === 'OFF' ? "e.g., Place the products on the wooden table..." : "Analysis and Rules will appear here..."}
                />

                {mode !== 'OFF' && (styleImages.length > 0 || productImages.length > 0) && (
                  <button
                    onClick={handleReAnalyze}
                    disabled={isAnalyzingStyle}
                    className="absolute top-3 right-3 p-2 bg-black/80 backdrop-blur-sm border border-gray-800 rounded-lg text-gray-500 hover:text-white hover:border-white transition-all shadow-lg group"
                    title="Re-analyze images and refresh prompt"
                  >
                    <svg 
                      xmlns="http://www.w3.org/2000/svg" 
                      fill="none" 
                      viewBox="0 0 24 24" 
                      strokeWidth={1.5} 
                      stroke="currentColor" 
                      className={`w-4 h-4 ${isAnalyzingStyle ? 'animate-spin text-white' : 'group-hover:rotate-180 transition-transform duration-500'}`}
                    >
                      <path strokeLinecap="round" strokeLinejoin="round" d="M16.023 9.348h4.992v-.001M2.985 19.644v-4.992m0 0h4.992m-4.993 0 3.181 3.183a8.25 8.25 0 0 0 13.803-3.7M4.031 9.865a8.25 8.25 0 0 1 13.803-3.7l3.181 3.182m0-4.991v4.99" />
                    </svg>
                  </button>
                )}
              </div>
            </div>
          </div>

          {/* RIGHT COLUMN: Output */}
          <div className="lg:col-span-7 flex flex-col gap-6">
            <div className="bg-gray-900 border border-gray-800 rounded-2xl p-2 h-[600px] flex flex-col relative overflow-hidden group">
              <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-20 pointer-events-none"></div>

              {generatedImage ? (
                <div className="relative w-full h-full flex items-center justify-center bg-black rounded-xl overflow-hidden group/image">
                   <img 
                    src={generatedImage} 
                    alt="Generated Product" 
                    className="max-w-full max-h-full object-contain shadow-2xl cursor-zoom-in transition-transform duration-300 group-hover/image:scale-[1.01]"
                    onClick={() => setIsLightboxOpen(true)}
                  />
                  {/* Overlay Removed as per requirement to move download button below */}
                  <div className="absolute bottom-4 left-1/2 -translate-x-1/2 opacity-0 group-hover/image:opacity-100 transition-opacity bg-black/50 backdrop-blur-md px-3 py-1 rounded-full text-xs text-white/80 pointer-events-none border border-white/20">
                    Click to enlarge
                  </div>
                </div>
              ) : (
                <div className="w-full h-full flex flex-col items-center justify-center text-gray-500 gap-4 bg-gray-950 rounded-xl overflow-hidden relative">
                  {isGenerating ? (
                    <div className="absolute inset-0 z-20 bg-black flex flex-col items-center justify-center">
                      <div className="w-full h-48 relative flex items-center overflow-hidden">
                         {/* Flying Container - Moves from Left to Right */}
                         <div className="absolute left-0 flex flex-col items-center gap-4" style={{ animation: 'fly-right 6s linear infinite' }}>
                            {/* Realistic Dove SVG */}
                            <svg width="64" height="64" viewBox="0 0 100 100" fill="none" xmlns="http://www.w3.org/2000/svg" className="text-white drop-shadow-[0_0_15px_rgba(255,255,255,0.8)] overflow-visible">
                                {/* Body */}
                                <path 
                                  d="M10,50 Q25,55 40,52 Q55,48 70,50 Q85,55 95,45 Q80,35 60,40 Q45,45 30,48 Q15,48 10,50 Z" 
                                  fill="currentColor" 
                                />
                                {/* Back Wing (Lower Layer) */}
                                <g className="origin-[45px_45px]" style={{ animation: 'wing-flap 0.5s ease-in-out infinite alternate' }}>
                                   <path d="M45,48 Q60,30 80,15 Q70,40 55,50 Z" fill="currentColor" opacity="0.8" />
                                </g>
                                {/* Front Wing (Upper Layer) */}
                                <g className="origin-[45px_48px]" style={{ animation: 'wing-flap-front 0.5s ease-in-out infinite alternate' }}>
                                   <path d="M45,48 Q65,25 90,5 Q75,35 60,52 Z" fill="currentColor" />
                                </g>
                            </svg>
                            <span className="text-white text-[10px] tracking-[0.2em] uppercase font-light drop-shadow-md">loading</span>
                         </div>
                      </div>
                    </div>
                  ) : (
                    <>
                      <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1} stroke="currentColor" className="w-24 h-24 opacity-20">
                        <path strokeLinecap="round" strokeLinejoin="round" d="m2.25 15.75 5.159-5.159a2.25 2.25 0 0 1 3.182 0l5.159 5.159m-1.5-1.5 1.409-1.409a2.25 2.25 0 0 1 3.182 0l2.909 2.909m-18 3.75h16.5a1.5 1.5 0 0 0 1.5-1.5V6a1.5 1.5 0 0 0-1.5-1.5H3.75A1.5 1.5 0 0 0 2.25 6v12a1.5 1.5 0 0 0 1.5 1.5Zm10.5-11.25h.008v.008h-.008V8.25Zm.375 0a.375.375 0 1 1-.75 0 .375.375 0 0 1 .75 0Z" />
                      </svg>
                      <p className="text-gray-500">Result will appear here</p>
                    </>
                  )}
                </div>
              )}
            </div>

            {/* Download Options - Directly Below Result */}
            {generatedImage && (
              <div className="relative z-20">
                <button
                  onClick={() => setShowDownloadMenu(!showDownloadMenu)}
                  disabled={isUpscaling}
                  className="w-full py-3 bg-gray-900 border border-gray-800 rounded-xl hover:bg-gray-800 hover:border-gray-600 transition-colors flex items-center justify-center gap-2 text-sm font-medium text-white"
                >
                  {isUpscaling ? (
                    <>
                      <svg className="animate-spin h-4 w-4 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                      </svg>
                      Upscaling to 4K...
                    </>
                  ) : (
                    <>
                      <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-5 h-5">
                        <path strokeLinecap="round" strokeLinejoin="round" d="M3 16.5v2.25A2.25 2.25 0 0 0 5.25 21h13.5A2.25 2.25 0 0 0 21 18.75V16.5M12 9.75v10.5m0 0L7.5 15.75M12 20.25l4.5-4.5M12 3v9" />
                      </svg>
                      Download Options
                      <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className={`w-4 h-4 transition-transform ${showDownloadMenu ? 'rotate-180' : ''}`}>
                        <path strokeLinecap="round" strokeLinejoin="round" d="m19.5 8.25-7.5 7.5-7.5-7.5" />
                      </svg>
                    </>
                  )}
                </button>

                {showDownloadMenu && !isUpscaling && (
                  <div className="absolute bottom-full left-0 w-full mb-2 bg-gray-900 border border-gray-700 rounded-xl shadow-2xl p-2 grid grid-cols-2 gap-2 animate-in slide-in-from-bottom-2 fade-in duration-200">
                    <button onClick={() => handleDownload('png', '2K')} className="flex flex-col items-center justify-center p-3 rounded-lg hover:bg-gray-800 transition-colors group">
                      <span className="text-white font-bold text-sm">PNG 2K</span>
                      <span className="text-[10px] text-gray-500 group-hover:text-gray-400">Standard Quality</span>
                    </button>
                    <button onClick={() => handleDownload('jpg', '2K')} className="flex flex-col items-center justify-center p-3 rounded-lg hover:bg-gray-800 transition-colors group">
                       <span className="text-white font-bold text-sm">JPG 2K</span>
                       <span className="text-[10px] text-gray-500 group-hover:text-gray-400">Standard Quality</span>
                    </button>
                  </div>
                )}
              </div>
            )}

            {/* Action Button */}
            <div className="relative group w-full">
              {/* Only show the glowing effect if enabled */}
              {!(productImages.length === 0 || isGenerating || isAnalyzingStyle || isUpscaling) && (
                <div className="absolute -inset-[3px] rounded-xl opacity-90 blur-md bg-gradient-to-r from-[#FF0000] via-[#00FF00] via-[#0000FF] to-[#FF0000] animate-rgb-flow group-hover:opacity-100 transition-all duration-300"></div>
              )}

              <button
                onClick={handleGenerate}
                disabled={productImages.length === 0 || isGenerating || isAnalyzingStyle || isUpscaling}
                className={`
                  relative w-full py-4 px-6 rounded-xl font-bold text-lg transition-all duration-300 transform active:scale-[0.98]
                  flex items-center justify-center gap-3 border
                  ${productImages.length === 0 || isGenerating || isAnalyzingStyle || isUpscaling
                    ? 'bg-gray-900 border-gray-800 text-gray-500 cursor-not-allowed' 
                    : 'bg-black border-transparent text-white shadow-2xl'
                  }
                `}
              >
                {isGenerating ? (
                  <>
                    <svg className="animate-spin -ml-1 mr-3 h-5 w-5" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                      <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                      <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                    </svg>
                    Processing...
                  </>
                ) : (
                  <>
                    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" className="w-5 h-5 text-white">
                      <path fillRule="evenodd" d="M9.315 7.584C12.195 3.883 16.695 1.5 21.75 1.5a.75.75 0 0 1 .75.75c0 5.056-2.383 9.555-6.084 12.436h.001c-3.3 2.567-6.93 2.567-9.691 2.567H3.25C1.83 17.253.375 18.064.375 20.25a.75.75 0 0 0 .75.75h21.75a.75.75 0 0 0 .75-.75c0-2.186-1.455-2.997-2.875-2.997H16.19c-2.76 0-6.39 0-9.69-2.567C2.882 11.952.5 7.452.5 2.396a.75.75 0 0 1 .75-.75c5.055 0 9.555 2.383 12.436 6.084l-3.375 3.375-3.001-3.52Z" clipRule="evenodd" />
                    </svg>
                    <span className="text-white drop-shadow-[0_0_10px_rgba(255,255,255,0.7)]">
                      Generate Image
                    </span>
                  </>
                )}
              </button>
            </div>

            {error && (
              <div className="p-4 bg-gray-900 border border-white text-white rounded-lg text-sm">
                {error}
              </div>
            )}

            {/* History Section */}
            {history.length > 0 && (
              <div className="bg-gray-900 border border-gray-800 rounded-2xl p-6">
                <div className="flex items-center justify-between mb-4">
                  <h3 className="text-sm font-semibold text-gray-500 uppercase tracking-wider">Recent Generations</h3>
                  <button 
                    onClick={() => setHistory([])}
                    className="text-xs text-gray-500 hover:text-white transition-colors"
                  >
                    Clear History
                  </button>
                </div>
                <div className="flex gap-4 overflow-x-auto pb-2 scrollbar-thin scrollbar-thumb-gray-800 scrollbar-track-transparent">
                  {history.map(item => (
                    <button
                      key={item.id}
                      onClick={() => setGeneratedImage(item.imageUrl)}
                      className={`relative flex-shrink-0 w-24 h-24 rounded-lg overflow-hidden border-2 transition-all group ${
                        generatedImage === item.imageUrl 
                          ? 'border-white ring-2 ring-white/20' 
                          : 'border-transparent hover:border-gray-600'
                      }`}
                    >
                      <img 
                        src={item.imageUrl} 
                        alt="History item" 
                        className="w-full h-full object-cover" 
                      />
                      <div className="absolute inset-0 bg-black/0 group-hover:bg-black/10 transition-colors" />
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>
      </main>

      {/* Lightbox Overlay */}
      {isLightboxOpen && generatedImage && (
        <div 
          className="fixed inset-0 z-[100] flex items-center justify-center bg-black/95 backdrop-blur-md p-4 animate-in fade-in duration-200"
          onClick={() => setIsLightboxOpen(false)}
        >
          {/* Close Button */}
          <button 
            className="absolute top-6 right-6 text-gray-400 hover:text-white transition-colors bg-gray-900 rounded-full p-2 hover:bg-gray-800 border border-gray-800 z-50"
            onClick={(e) => {
              e.stopPropagation();
              setIsLightboxOpen(false);
            }}
          >
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-8 h-8">
              <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>

          <img 
            src={generatedImage} 
            alt="Full Resolution Result" 
            className="max-w-full max-h-full object-contain shadow-2xl rounded-sm border border-gray-800"
            onClick={(e) => e.stopPropagation()}
          />
        </div>
      )}
    </div>
  );
};

export default App;
